        $firebaseUserId = Session::get('firebase_user_id');

        if (!$firebaseUserId) {
            // Attempt to authenticate the user using the ID token from the request header
            $idToken = $request->header('Authorization');

            if ($idToken) {
                try {
                    $tokenVerifier = new TokenVerifier(config('firebase.auth_domain'));
                    $token = $tokenVerifier->verifyIdToken($idToken);
                    $firebaseUserId = $token->uid;

                    Session::put('firebase_user_id', $firebaseUserId);
                } catch (RevokedTokenException $e) {
                    // Token is revoked
                    return response()->json(['error' => 'Unauthorized: Revoked token'], 401);
                } catch (\Exception $e) {
                    // Other Firebase authentication errors
                    return response()->json(['error' => 'Unauthorized: Firebase authentication error'], 401);
                }
            }
        }

        if (!$firebaseUserId) {
            return response()->json(['error' => 'Unauthorized: No Firebase user ID found'], 401);
        }

        return $next($request);
    }
}
