And a separate class for the query execution logic:

```java
@Component
public class QueryExecutor {

    @Value("${sql.query.file}")
    private String sqlQueryFilePath;

    @Value("${output.file}")
    private String outputFile;

    @Autowired
    private DataSource dataSource; // Inject DataSource

    public void executeQueryAndStoreResults() throws IOException, SQLException {
        String sqlQuery = readSqlQueryFromFile(sqlQueryFilePath);
        List<Map<String, Object>> results = executeQuery(sqlQuery);
        storeResultsToFile(results, outputFile);
    }

    private String readSqlQueryFromFile(String filePath) throws IOException {
        // Read SQL query from file
        return new String(Files.readAllBytes(Paths.get(filePath)));
    }

    private List<Map<String, Object>> executeQuery(String sqlQuery) throws SQLException {
        // Execute SQL query and return results
        try (Connection connection = dataSource.getConnection();
             PreparedStatement preparedStatement = connection.prepareStatement(sqlQuery)) {

            ResultSet resultSet = preparedStatement.executeQuery();
            List<Map<String, Object>> results = new ArrayList<>();

            ResultSetMetaData metaData = resultSet.getMetaData();
            int columnCount = metaData.getColumnCount();

            while (resultSet.next()) {
                Map<String, Object> row = new HashMap<>();
                for (int i = 1; i <= columnCount; i++) {
                    row.put(metaData.getColumnName(i), resultSet.getObject(i));
                }
                results.add(row);
            }

            return results;
        }
    }

    private void storeResultsToFile(List<Map<String, Object>> results, String filePath) throws IOException {
        // Store results to file
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(filePath))) {
            for (Map<String, Object> row : results) {
                writer.write(row.toString()); // Simple string representation
                writer.newLine();
            }
        }
    }
}
